from ute_common_abstract_core.config import Config


def get_message_sources_configuration(testline_configuration):
    """
    Returns configuration of all MessageSources active on given Testline from given testline_configuratoin
    :param testline_configuration: ute_ue configuration specific for given Testline
    :return: active message sources config
    """
    message_sources_configuration = testline_configuration.get('MESSAGE_SOURCES', [])
    return message_sources_configuration


def get_message_sources_configuration_from_tl():
    """
    Returns configuration of all MessageSources active on given Testline
    Encapsulates getting path to config file, reads it and returns needed section
    :return: active message sources config
    """
    testline_configuration = Config().get_config()
    message_sources_configuration = get_message_sources_configuration(testline_configuration)
    return message_sources_configuration
